// Blog posts, from the WordPress REST API.
//
// Posts are ordinary WordPress content (not Oxygen), so their bodies come
// through as real HTML and are converted here into a small block structure —
// heading / paragraph / list / image. Rendering blocks rather than injecting
// raw HTML keeps the blog inside this site's own typography and avoids
// dangerouslySetInnerHTML.
//
// GENERATED from the live site. Files that consume this:
//   src/components/property/PostBody.tsx
//   src/components/property/PostGrid.tsx
//   src/app/**/discover/[slug]/page.tsx and the standalone post routes
//
// Note: the live site also publishes a post at /ubud/retreat/host-your-own/,
// which collides with the PAGE of the same URL. WordPress serves the page, so
// the post is unreachable there — it is omitted here for the same reason.

export type PostBlock =
  | { kind: "heading"; text: string }
  | { kind: "paragraph"; text: string }
  | { kind: "list"; items: string[] }
  | { kind: "image"; src: string };

export type Post = {
  /** Full live path, e.g. "/ubud/discover/hatha-yoga". */
  path: string;
  property: "seminyak" | "ubud";
  title: string;
  /** ISO date (YYYY-MM-DD). */
  date: string;
  excerpt: string;
  image: string;
  blocks: PostBlock[];
};

